    t[169208] = { name = "Вінець Вічної Удачі", fen = "A circlet of flowers worn to bring good fortune all year long.", fua = "Вінок із квітів, що його носять, аби притягувати удачу впродовж усього року." }
    t[169219] = { name = "Безалкогольний Дегустаційний Кухоль Хмільного Свята", fen = "Alcohol-free brew in a fun, throwable mug!", fua = "Безалкогольний напій у кумедному кухлі, яким можна жбурлятися!" }
    t[169397] = { name = "Адміралтейський Ель", fen = "A light brew with a pleasant hop on the end, Admiralty Ale is a great first step into the world of Kul Tiran brew!", fua = "Легкий трунок із приємною хмелевою ноткою наприкінці. Адміралтейський Ель — чудовий перший крок у світ кул-тіраської пивоварні!" }
    t[169436] = { name = "Вогнекровний Стаут", fen = "A brew that will put a fire in your boots... as well as your gut!", fua = "Трунок, що розпалить вогонь у ваших чоботях... та й у нутрощах!" }
    t[169439] = { name = "Ель Темного Заліза", fen = "A timeless classic.", fua = "Позачасова класика." }
    t[169441] = { name = "Мед Лазурової Імли", fen = "An oft-enjoyed craft of the draenei's time on Azeroth.", fua = "Напій, яким часто тішилися дренеї за свого часу на Азероті." }
    t[169442] = { name = "Екзодарське Мартіні", fen = "Crashed, not stirred.", fua = "Розбите, а не збовтане." }
    t[169443] = { name = "Шнапс Тінемісяччя", fen = "Arkanon pour-us another!", fua = "Арканоне, налий-но ще!" }
    t[169448] = "Бездонний Кухоль Хмільного Свята"
    t[169450] = { name = "Наповнений Бездонний Кухоль Хмільного Свята", fen = "Barleybrew filled, Brewfest approved.", fua = "Налито Ячмінним Варом, схвалено Хмільним святом." }
    t[169452] = { name = "Наповнений Бездонний Кухоль Хмільного Свята", fen = "Thunderbrew's got ya covered!", fua = "Тандербрю про вас подбають!" }
    t[169453] = { name = "Наповнений Бездонний Кухоль Хмільного Свята", fen = "It's not just ogre brew, it's Gordok brew.", fua = "Це не просто оґряче пиво, це ґордоцьке пиво." }
    t[169454] = { name = "Наповнений Бездонний Кухоль Хмільного Свята", fen = "The path for good brew ends at Drohn's Distillery.", fua = "Шлях до доброго трунку веде до Ґуральні Дрона." }
    t[169455] = { name = "Наповнений Бездонний Кухоль Хмільного Свята", fen = "T'chali's Voodoo Brew is 98% body part free.", fua = "Вуду-вариво Т'чалі на 98% не містить частин тіл." }
    t[169458] = { name = "Вол'дунська Самогонка", fen = "Vulpera-made desert hooch, stored in a dried gourd. Deliciously brewed during desert travel!", fua = "Пустельна горілка від вульпер, що зберігається в сухій тиквині. Чудово настоюється під час подорожі пустелею!" }
    t[169459] = { name = "Сауридський Сьорбун", fen = "Goes down as smooth as a saurid's scales!", fua = "Іде так само гладко, як луска саурида!" }
    t[169460] = { name = "Дуже Дуже Дуже Старосвітський", fen = "A tortollan favorite.", fua = "Улюбленець тортоланів." }
    t[169461] = "Гірлянда зі Збіжжя"
    t[169462] = { name = "Нічне Вино в Коробці", fen = "Cheap nightwine on the go!", fua = "Дешеве нічне вино з собою!" }
    t[169463] = { name = "Нічновинний Прохолодник", fen = "Infuse yourself with the energy of the Nightwell... and also fruit juice!", fua = "Просочіться енергією Нічного Джерела... а ще фруктовим соком!" }
    t[169464] = { name = "Іскристий Шприц Сурамара", fen = "A delicious way to bluff your way through your next masquerade.", fua = "Смачний спосіб пройти крізь наступний маскарад нерозкритим." }
    t[169466] = { name = "Вічноцвітний ІПА", fen = "Brewed with botani hops.", fua = "Зварений на хмелі ботані." }
    t[169467] = { name = "Лагер Судьби", fen = "For when you realize that a good brew is more important than a good hammer.", fua = "Для тих хвилин, коли усвідомлюєш, що добрий трунок важливіший за добрий молот." }
    t[169468] = { name = "Прадідівський Ель", fen = "A beer to cheers your ancestors, served in a traditional frostboar tusk.", fua = "Пиво, щоб виголосити тост за ваших предків, подане в традиційному іклі морозного вепра." }
    t[169469] = { name = "Маг'хелада", fen = "A spicy take on a more traditional ale.", fua = "Гостра версія традиційнішого елю." }
    t[169521] = { name = "Молочний Стаут Маслокопита", fen = "Butterhoof's best!", fua = "Найкраще від Маслокопита!" }
    t[169527] = { name = "Громовий Спотикач", fen = "Highmountain stands... except after drinking this!", fua = "Високогір'я стоїть... аж поки не вип'єш оцього!" }
    t[169599] = { name = "Жетон Чемпіона Об'їдалок", fen = "Turn in five to receive the Brewfest Chowdown Trophy.", fua = "Здайте п'ять, щоб отримати Трофей Об'їдалок Хмільного свята." }
    t[169865] = "Трофей Об'їдайла Хмільного Свята"
    t[170083] = { name = "Посох Місячних Квітів", fen = "It seems a simple grassy staff. You feel no power from within it.", fua = "Здається простим трав'янистим посохом. Ти не відчуваєш у ньому жодної сили." }
    t[170084] = { name = "Благословенний Посох Місячних Квітів", fen = "When you hold the staff, you feel a surge of power from within. Flowers seem to periodically bloom and disappear across its length.", fua = "Коли тримаєш посох, відчуваєш приплив сили зсередини. По всій його довжині періодично наче розпускаються й зникають квіти." }
    t[170202] = { name = "Швайдерброй", fen = "The signature brew of renowned Dark Iron brewer Blackguard Shwayder.", fua = "Фірмове пиво уславленого пивовара з темнозалізних дворфів, Чорногвардійця Швайдера." }
    t[170205] = { name = "Вінець Безмежної Відваги", fen = "A circlet of flowers worn to bring courage all year long.", fua = "Вінець із квітів, що носять задля відваги впродовж усього року." }
    t[170206] = { name = "Вінець Безмежного Процвітання", fen = "A circlet of flowers worn to bring prosperity all year long.", fua = "Вінець із квітів, що носять задля процвітання впродовж усього року." }
    t[170207] = { name = "Вінець Вічної Пам'яті", fen = "A circlet of flowers worn to bring solemnity all year long.", fua = "Вінець із квітів, що носять задля урочистості впродовж усього року." }
    t[170278] = { name = "Квітка Стійкості", fen = "For courage in the face of adversity.", fua = "За мужність перед лицем негараздів." }
    t[170279] = { name = "Квітка Щирості", fen = "For the courage to stay true to your beliefs.", fua = "За мужність лишатися вірним своїм переконанням." }
    t[170280] = { name = "Квітка Бадьорості", fen = "For physical strength and good health.", fua = "За фізичну силу та міцне здоров'я." }
    t[170281] = { name = "Квітка Достатку", fen = "For abundance in resources and savings.", fua = "За багатство ресурсів та заощаджень." }
    t[170282] = { name = "Квітка Миру", fen = "For longevity of life.", fua = "За довге життя." }
    t[170283] = { name = "Квітка Блаженства", fen = "For happiness in life.", fua = "За щастя в житті." }
    t[170296] = { name = "Квітка Співчуття", fen = "For sympathy to yourself and others.", fua = "За співчуття до себе та інших." }
