    t[170321] = { name = "Квітка Удачі", fen = "For the blessing of forces greater than yourself.", fua = "За благословення сил, могутніших за тебе." }
    t[170322] = { name = "Квітка Щедрості", fen = "For sharing your fortune with those around you.", fua = "За те, що ділишся своїм щастям з тими, хто поруч." }
