    t[190814] = { name = "Бритва Мефістрота", fen = "Just what is needed when cutting things a little close.", fua = "Саме те, що треба, коли ріжеш на самій межі." }
    t[190816] = "«Стабільний» Паливний Елемент Підручного Коваля"
    t[190817] = { name = "Великий Щит Вартової", fen = "Because everybody loves tower defense.", fua = "Бо всі люблять оборону вежі." }
    t[190818] = { name = "Видобувач Артефактів Стімвідла", fen = "\"Faster than any shovel!\" - Gazrix Gearlock", fua = "«Швидший за будь-яку лопату!» — Газрікс Шестернезамок" }
    t[190819] = { name = "Довгий Лук Смарагдового Охоронця", fen = "\"The Emerald Dream is the charge of the green dragons. \n\n\n\nWe will defend it, no matter the cost.\"\n\n\n\n- Merithra", fua = "«Смарагдовий Сон — обов'язок зелених драконів. \n\n\n\nМи боронитимемо його, хай там що».\n\n\n\n— Мерітра" }
    t[190820] = "Ручна Сокира Невгамовної Порожнечі"
    t[190821] = { name = "Бойовий Посох Сонячного Шпиля", fen = "Said to contain a fragment of An'she's power.", fua = "Кажуть, що в ньому міститься уламок сили Ан'ше." }
    t[190822] = "Алебарда Карателя Мо'арґів"
    t[190824] = { name = "Дворучний Меч Вірного Майстра Клинка", fen = "The only thing more sure than the sharpness of this blade is the loyalty of its wielder.", fua = "Єдине, що певніше за гостроту цього клинка, — це вірність того, хто його тримає." }
    t[190825] = "Багряний Плащ Мандрівника"
    t[190826] = "Багряний Шарф Мандрівника"
    t[190827] = "Багряний Плащ Волоцюги"
    t[190828] = "Багряний Каптур Волоцюги"
    t[190829] = { name = "Шаль Плинної Магії", fen = "Crafted by the finest arctailor in Suramar.", fua = "Виготовлена найкращим арканним кравцем Сурамару." }
    t[190830] = "Чоботи Божевільного Злодія"
    t[190831] = { name = "Гострий Як Бритва Кукрі", fen = "Perfect for clearing those pesky jungles.", fua = "Ідеальний для розчищення цих набридливих джунглів." }
    t[190832] = { name = "Гравіюваний Бойовий Молот Аколіта", fen = "The mark of a Vrykul acolyte can be seen engraved on the head.", fua = "На обусі видно вигравіюваний знак врайкульського аколіта." }
    t[190833] = { name = "Гізарма Крокулів", fen = "Hatuun's Ridgestalkers require only a stable footing and a steady hand.", fua = "Гірським слідопитам Гатууна потрібні лише надійна опора під ногами й тверда рука." }
    t[190842] = { name = "Кулаки Полярної Люті", fen = "An effective icebreaker, literally and figuratively.", fua = "Дієвий криголам, у прямому й переносному сенсі." }
    t[190843] = { name = "Паща Люті", fen = "Despite the old age, it is still just the Maw of Rage.", fua = "Попри поважний вік, це все ще лише Паща Люті." }
    t[190844] = { name = "Дворучний Меч Звитяжця Валар'ярів", fen = "Odyn outfitted his champions with only the best weaponry.", fua = "Одін споряджав своїх звитяжців лише найкращою зброєю." }
    t[190845] = "Штани Урочистого Вартового"
    t[190846] = { name = "Розтрощений Шпиль Порожнечі", fen = "The call of the void is unrelenting.", fua = "Поклик Порожнечі невблаганний." }
    t[190847] = "Жало Вбивці Смертної Мантії"
    t[190848] = "[DNT] Do not use"
    t[190849] = { name = "Молоток Майстра-Коваля", fen = "Whether from cooking inedible food or bonking enemies on the head, this weapon will cause injury.", fua = "Чи то ви готуєте нею неїстівні страви, чи лупите ворогів по голові — ця зброя завдасть болю." }
    t[190850] = { name = "Комплект: Багряні Шати Мандрівника", fen = "Includes a scarf and a cloak.", fua = "Містить шарф і плащ." }
    t[190851] = { name = "Комплект: Багряне Вбрання Волоцюги", fen = "Includes a hood and a cloak.", fua = "Містить каптур і плащ." }
    t[190854] = { name = "Грубо Зашитий Гаманець", fen = "Are the stitches the mark of an easy mark?", fua = "Чи ці шви — ознака легкої здобичі?" }
    t[190855] = { name = "Трояндовий Букетик", fen = "Never forget to stop and smell the roses.", fua = "Ніколи не забувайте спинитися й понюхати троянди." }
    t[190856] = { name = "Смердючий Букет", fen = "Some roses are better left unsmelled.", fua = "Деякі троянди краще не нюхати." }
    t[190857] = { name = "Визолочений Смарагдовий Довгий Плащ", fen = "Emerald warders use this cloak to blend into the dream, prepared for any threats that may come.", fua = "Смарагдові вартові використовують цей плащ, щоб зливатися зі Сном, готові до будь-яких загроз, що можуть постати." }
    t[190858] = "Пояс Захололих Жарин"
    t[190859] = { name = "Кручений Посох Учня", fen = "One of a Kirin Tor initiate's first assignments is using transmutation to shape a gnarled branch into a respectable staff. This one didn't pass.", fua = "Одне з перших завдань послушника Кірін-Тору — за допомогою трансмутації перетворити вузлувату гілку на гідний посох. Цей іспиту не склав." }
    t[190860] = { name = "Бо Послушника", fen = "A simple beginner's weapon.", fua = "Проста зброя для початківців." }
    t[190861] = "Пояс Захисника Вал'Шари"
    t[190869] = { name = "Сукня Попелястого Каменя", fen = "This style is all the rage in Emberstone Village.", fua = "Цей стиль зараз на піку моди в селищі Попелястого Каменя." }
    t[190870] = { name = "Щит Міської Варти", fen = "Left over from a Volunteer Guard Day promotion.", fua = "Залишок із кампанії до Дня Добровольця-Вартового." }
    t[190871] = { name = "Кулачний Щит Воїна", fen = "Sword and board for the Horde!", fua = "Меч і щит за Орду!" }
    t[190872] = "Кіраса Незворушного Вартового"
    t[190873] = { name = "Бойовий Молот Пихи", fen = "Hubris is the sin of the mortal races, and for it they must be punished.", fua = "Пиха — це гріх смертних народів, і за нього вони мають бути покарані." }
    t[190874] = { name = "Мерехтливий Скверний Молоток", fen = "The words \"Vindicator Velhari\" can be faintly seen inscribed upon the fel-saturated pomel.", fua = "На просякнутому скверною руків'ї ледь видно вигравіюваний напис «Заступниця Велгарі»." }
    t[190875] = { name = "Холодний Дотик Приречених", fen = "Death Acolytes would pass judgment on prisoners with these wands.", fua = "Аколіти Смерті виносили вирок в'язням цими чарівними паличками." }
    t[190876] = { name = "Філігранна Левова Паща", fen = "A forgotten relic of Lordaeronian ceremony, the shield still offers substantial protection despite its extravagance.", fua = "Забута реліквія церемоній Лордерону, цей щит досі дає неабиякий захист попри всю свою вигадливість." }
    t[190882] = "Сніжний Плащ Волоцюги"
    t[190883] = "Сніжний Плащ Мандрівника"
