    t[190886] = { name = "Витончені Білі Вечірні Рукавички", fen = "The finest of gloves for the finest of occasions. Don't paint any eggs with these gloves on.", fua = "Найвитонченіші рукавички для найвитонченіших нагод. Тільки не фарбуйте в них яйця." }
    t[190887] = { name = "Церемоніальна Накидка Верховного Лорда", fen = "Reserved for only the most important occasions this drape is revered by the desert clans.", fua = "Зарезервована лише для найважливіших нагод, ця накидка шанована кланами пустелі." }
