    t[190893] = { name = "Самоцвітний Плащ Вал'кір", fen = "The icy gems were gifts of the Lich King to a Valkyrion queen long ago.", fua = "Льодяні самоцвіти колись давно були дарунками Короля-Ліча королеві вал'кір." }
