    t[202238] = { name = "Перстень-печатка наглядача Ґранта", fen = "A simple ring, made up of intertwining metal, with a small stone set, oddly enough, on the inside.", fua = "Простий перстень із переплетеного металу, у який, як не дивно, з внутрішнього боку вставлено маленький камінець." }
    t[202248] = { name = "Замерзла Тінь", fen = "Pulled from the forgotten depths of the Nexus, the blade radiates a biting cold.", fua = "Видобутий із забутих глибин Нексусу, цей клинок струмує пронизливим холодом." }
    t[202267] = { name = "Перстень-Печатка Клессінґтона", fen = "An odd combination of four separate signets twisted to fit together into one. A slight warmth radiates from inside, with the familiar sharp scent of arcane magic.", fua = "Дивна сполука чотирьох окремих печаток, переплетених так, щоб скластися в одну. Зсередини струмує легке тепло разом зі знайомим різким запахом чародійської магії." }
