    t[203431] = "Набір: Тягар Невблаганного Правосуддя"
    t[203475] = { name = "Термінове Виклик до Стормвінду", fen = "Rather inconspicuous, with a plain, unmarked wax seal.", fua = "Доволі непримітне, з простою непозначеною восковою печаткою." }
    t[204063] = { name = "Щоденник Віндзора", fen = "One of many. Contains useful information about Onyxia and her plans in Stormwind but has seen heavy use as a chew toy by hungry wolves.", fua = "Один із багатьох. Містить корисні відомості про Оніксію та її задуми у Стормвінді, проте добряче пошарпаний голодними вовками, що гризли його, мов іграшку." }
    t[204081] = { name = "Рукавиця-Шматувалка", fen = "Not recommended for those whose love language is physical touch.", fua = "Не рекомендовано тим, для кого мова любові — дотики." }
    t[204082] = { name = "Чутливий Приятель", fen = "Be very wary of making them emotional.", fua = "Будьте дуже обережні, щоб не зачепити його почуття." }
    t[204086] = { name = "С.К.А.Н.Е.Р. Mk3", fen = "Scanning Contraption Armed with Nightsight, Neuro-reading, and Encasing Reticle.", fua = "Скануючий Контрапт, Армований Нічнобаченням, Нейрозчитуванням і Обхопним Ретикулом." }
    t[204091] = { name = "Ракетний Шредер 9001", fen = "Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.", fua = "Навчає вас прикликати цього їздового звіра. Цей звір змінюється залежно від вашого вміння верхової їзди та місцеперебування." }
    t[204171] = { name = "Перстень-Печатка Карательки Дженнів", fen = "A simple ring, made up of intertwining metal, with a small stone set, oddly enough, on the inside.", fua = "Простий перстень із переплетеного металу, у який, як не дивно, з внутрішнього боку вставлено маленький камінець." }
    t[204172] = { name = "Перстень-Печатка Карательки Тери", fen = "A simple ring, made up of intertwining metal, with a small stone set, oddly enough, on the inside.", fua = "Простий перстень із переплетеного металу, у який, як не дивно, з внутрішнього боку вставлено маленький камінець." }
    t[204173] = { name = "Перстень-Печатка Карателя Горба", fen = "A simple ring, made up of intertwining metal, with a small stone set, oddly enough, on the inside.", fua = "Простий перстень із переплетеного металу, у який, як не дивно, з внутрішнього боку вставлено маленький камінець." }
