    t[208663] = { name = "Шати Відродження Ашамани", fen = "Worn by the Ashen Druids, these vestments pay homage to the fallen Wild God, Ashamane.", fua = "Це вбрання, що його носять Попелясті друїди, віддає шану полеглій дикій богині Ашамані." }
    t[208664] = { name = "Благословення Відродження Ашамани", fen = "Engraved with the Mark of the Ashen Druids.", fua = "Викарбувано Знаком Попелястих друїдів." }
    t[208665] = { name = "Обплетений Павутиною Саронітовий Екзоскелет", fen = "The webs of the nerubians aren't just for decor.", fua = "Павутиння нерубів не лише для оздоби." }
    t[208666] = { name = "Обплетена Павутиною Саронітова Зброя", fen = "Sharp enough to cut through nerubian silk.", fua = "Достатньо гостра, щоб розтинати нерубіанський шовк." }
    t[208667] = { name = "Полум'я Богохульника Натрези", fen = "Strike fear into any demon's heart with your flame's controlled chaos.", fua = "Вселяйте жах у серце будь-якого демона керованим хаосом свого полум'я." }
    t[208668] = { name = "Глефи Богохульника Натрези", fen = "This aerodynamic design will help chase down any demon.", fua = "Цей аеродинамічний дизайн допоможе наздогнати будь-якого демона." }
    t[208669] = { name = "Подоба Одержимого Вартового", fen = "The spirit inhabiting this armor is great company.", fua = "Дух, що живе в цій броні, — приємна компанія." }
    t[208671] = { name = "Арсенал Одержимого Вартового", fen = "The way of the Watcher is silent and deadly.", fua = "Шлях вартового тихий і смертоносний." }
    t[208672] = { name = "Самоцвіти Звабливого Поклику", fen = "No one can resist temptation.", fua = "Ніхто не може опиратися спокусі." }
    t[208673] = { name = "Знаряддя Звабливого Поклику", fen = "The way of the watcher is silent and deadly.", fua = "Шлях вартового тихий і смертоносний." }
    t[208674] = { name = "Трофеї Дикого Чемпіона", fen = "No beast is a match to our champion.", fua = "Жоден звір не зрівняється з нашим чемпіоном." }
    t[208675] = { name = "Агресія Дикого Чемпіона", fen = "As pale as the moon, as deadly the fang.", fua = "Блідий, мов місяць, смертоносний, мов ікло." }
