    t[208699] = { name = "Регалії Бойового Магістра", fen = "None were more skilled in the mastery of arcane than the High Elven Magisters of Quel'Thalas.", fua = "Ніхто не володів таємною магією краще за магістрів-високоельфів Квел'Таласу." }
    t[208700] = { name = "Чари Бойового Магістра", fen = "The Magisters studied many years to protect Quel'Thalas and so weapons to bolster their skills were fashioned to assist that effort.", fua = "Магістри багато років навчалися, щоб захистити Квел'Талас, тож на допомогу їм було створено зброю, що підсилює їхню майстерність." }
