    t[208725] = { name = "Луска Срібного Скнари", fen = "Forged by an unknown chronosmith at an unknown period in time.", fua = "Викувано невідомим хроноковалем у невідому добу." }
    t[208726] = { name = "Скарб Срібного Скнари", fen = "Fashioned by an ancient blacksmith, the chronosmiths ventured to their time to create these weapons for a future need. In time that need will become clearer.", fua = "Викувані прадавнім ковалем — хроноковалі вирушили в його час, щоб створити цю зброю для майбутньої потреби. З часом ця потреба стане яснішою." }
    t[208727] = { name = "Маскування Мисливця на Рогоступів", fen = "While preparing for a hornstrider hunt experienced hunters will don this ceremonial set to inspire the green hunters on their first hunt.", fua = "Готуючись до полювання на рогоступів, досвідчені мисливці вбираються в це церемоніальне вбрання, щоб надихнути новачків на першу здобич." }
    t[208728] = { name = "Вподобання Мисливця на Рогоступів", fen = "Known for their prowess and ferocity the hornstriders make an excellent hunt and even more excellent materials for weapons.", fua = "Відомі своєю звитягою та лютістю, рогоступи дарують чудове полювання й ще кращі матеріали для зброї." }
    t[208729] = { name = "Незворотність Виконавця Краг'ви", fen = "Crafted for the high priests of Krag'wa and the loas most ardent adherents.", fua = "Створено для верховних жерців Краг'ви та найвідданіших послідовників лоа." }
    t[208730] = { name = "Знаряддя Виконавця Краг'ви", fen = "Krag'wa's temples were guarded by loyal Zandalari wielding weapons designed to honor and protect.", fua = "Храми Краг'ви охороняли віддані зандалари, що тримали зброю, створену задля шани й захисту." }
    t[208735] = { name = "Відро Моторошних Ласощів", fen = "Some treats will have you feeling the burn.", fua = "Від деяких ласощів вам стане гаряче." }
    t[208763] = { name = "Тюбетейка Директора", fen = "The bony brim keeps the Light out of your eyes.", fua = "Кістяні криси захищають ваші очі від Світла." }
    t[208769] = { name = "Фоліант Томаса Томсона", fen = "A well-worn tome with the name Thomson scrawled on the cover.", fua = "Затертий фоліант, на обкладинці якого нашкрябано ім'я Томсон." }
    t[208785] = { name = "Калдорайські Клинки Традиціоналіста", fen = "These swords have been in use by kaldorei heroes for thousands of years.", fua = "Цими мечами герої калдораї користуються вже тисячі років." }
    t[208786] = { name = "Розкішний Капелюх Ніффенів", fen = "Were it not for our masterful negotiators, this hat would cost no less than 2500 tender.", fua = "Якби не наші вправні перемовники, цей капелюх коштував би не менше 2500 валюти." }
