    t[208825] = { name = "Гоночний Пояс Молодшого Хронометриста", fen = "From the 'I Can Be Andestrasz' collection of racing accessories comes a new do-it-yourself course creation kit!", fua = "З колекції гоночних аксесуарів «Я можу бути Андестразом» — новий набір для самостійного створення траси!" }
    t[208831] = { name = "Титанський Ключ Тіра", fen = "The key pulses with magic. Tyr's name is etched near the key's eye.", fua = "Ключ пульсує магією. Біля вушка ключа викарбувано ім'я Тіра." }
    t[208832] = "Титанський Ключ Тіра"
    t[208939] = { name = "Горрідар, Темний Клинок Розкришувача", fen = "Malice and hatred honed into a weapon designed to lay waste to entire worlds. Beware of any who envy such a blade.", fua = "Злоба й ненависть, виточені в зброю, призначену спустошувати цілі світи. Стережіться будь-кого, хто заздрить такому клинку." }
    t[208940] = { name = "Пісня Порожнечі, Посох Провісника", fen = "A gift of Dimensius bestowed at the height of the Black Empire. Those touched by shadow are drawn to its haunting whispers.", fua = "Дарунок Дименсіуса, піднесений у розквіт Чорної Імперії. Ті, кого торкнулася тінь, тягнуться до його тривожного шепоту." }
    t[208941] = { name = "М'торус, Кинджал Великого Задуму", fen = "Shadows cannot be allowed to fester. Disorder must be struck down wherever it takes hold. True children of the titans will heed their makers' call.", fua = "Тіням не можна дозволяти розростатися. Безлад слід нищити всюди, де він укорінюється. Справжні діти титанів дослухаються до поклику своїх творців." }
    t[208943] = { name = "Арсенал: Сховок Космічної Зброї", fen = "Armaments forged from the primal fabric of the cosmos. Who assembled this collection and why remains a mystery. Wielding them will draw the eye of those who covet such power.", fua = "Озброєння, викуване з первісної тканини космосу. Хто й навіщо зібрав цю колекцію - лишається загадкою. Володіння нею приверне погляди тих, хто прагне такої сили." }
    t[208959] = { name = "Таесавір, Меч Великого Задуму", fen = "An edge so sharp it could only be honed by Aggramar himself. Any who defy the will of the titans should beware its wielder.", fua = "Лезо настільки гостре, що нагострити його міг лише сам Аґрамар. Усім, хто кидає виклик волі титанів, варто стерегтися його власника." }
    t[208962] = { name = "Сітерас, Палаш Розкришувача", fen = "Forged from malignant chaos to strike at the target's heart. Those whose souls burn with all-consuming rage are drawn to its dark fire.", fua = "Викуваний зі злоякісного хаосу, щоб уражати ціль у серце. Ті, чиї душі палають усепоглинною люттю, тягнуться до його темного вогню." }
