    t[209336] = { name = "Комплект: Убрання Вершника Бур", fen = "You'll be the toast of every mead hall in Dornogal when you don this prestigious ensemble. The courage of the Stormriders is legendary among the earthen.", fua = "Ви станете окрасою кожного медового залу в Дорногалі, коли вдягнете цей величний комплект. Відвага Вершників Бур легендарна серед земних." }
    t[209417] = { name = "Комплект: Убрання Громового Вершника Бур", fen = "Only those who prove their speed and precision in the gryphon races will be given the honor of wearing this crackling ensemble.", fua = "Лише ті, хто доведе свою швидкість і влучність у перегонах грифонів, удостояться честі носити цей тріскотливий комплект." }
