    t[210867] = { name = "Жваві Камені Майстра Клинка", fen = "Carved from smoothed Talasite, these stones were reclaimed by Lantresor after assuming leadership of the Burning Blade clan.", fua = "Вирізьблені з гладенького таласиту, ці камені були повернені Лантресором після того, як він очолив клан Палаючого Клинка." }
