    t[210883] = { name = "Комплект: Шати Багряного Фанатика", fen = "The cloying scent of cathedral incense and righteous indignation clings to the fabric and metals within. Includes a robe, cloak and shield.", fua = "Тканина й метали всередині просякнуті нав'язливим запахом кафедрального ладану й праведного обурення. Містить робу, плащ і щит." }
