    t[212555] = { name = "Убрання Королівського Маскараду", fen = "This mask bears the unmistakable mark of the dusk lily.", fua = "Ця маска несе безпомильний знак сутінкової лілеї." }
    t[212556] = { name = "Убрання Сяйливого Маскараду", fen = "The latest fashion at the Suramar court.", fua = "Останній крик моди при дворі Сурамару." }
    t[212572] = { name = "Рожева Накидка Дуелянта на Плечі", fen = "A favorite of swashbucklers, a shoulder could be discarded to leave a sword arm free for boarding.", fua = "Улюблениця зайдиголов: одне плече можна скинути, щоб звільнити руку з мечем для абордажу." }
    t[212573] = { name = "Хмарна Накидка Дуелянта на Плечі", fen = "Sewn from a heavy brocade favored by Stormwindian nobles.", fua = "Пошита з важкої парчі, яку полюбляє стормвіндська знать." }
    t[212574] = { name = "Водяна Накидка Дуелянта на Плечі", fen = "The drapes of the Kul Tiran navy are woven to withstand the harsh winds of the Great Sea.", fua = "Тканини флоту Кул-Тіраса виткані так, щоб витримувати суворі вітри Великого моря." }
    t[212576] = { name = "Ката клану Блекрок", fen = "The deadly armaments of the Blackrock clan were as cruel as the heat of the Citadel's forges.", fua = "Смертоносна зброя клану Блекрок була така ж жорстока, як жар горнів цитаделі." }
    t[212577] = { name = "Арсенал: Небороджені Клинки", fen = "Akin to the mystical Quel'Serrar, and forged by the magesmith Luminarian, it was but the first of the Prismatic Blades.", fua = "Споріднений із містичним Квел'Серраром і скований магоковалем Люмінаріаном, він був лише першим серед призматичних клинків." }
