    t[212920] = { name = "Дика Синя Бойова Черепаха", fen = "Teaches you how to summon a rideable Savage Blue Battle Turtle. This mount swims fast and can't move very quickly on land, but it doesn't need to. It has cannons.", fua = "Навчає вас прикликати їздову дику синю бойову черепаху. Це їздове створіння швидко плаває, а суходолом рухається доволі повільно, але йому це й не потрібно. Адже в нього є гармати." }
    t[212940] = { name = "Комплект: Лавандова Колекція Весняного Гуляки", fen = "That spring shine is a certain sign that you feel as fine as you look.", fua = "Це весняне сяйво — певна ознака того, що ви почуваєтеся так само чудово, як і виглядаєте." }
