    t[223232] = { name = "Кіраса Мідного Водолаза", fen = "Functionality is more important than style at the depth you can dive in this suit.", fua = "На глибині, на яку можна занурюватися в цьому костюмі, функціональність важливіша за стиль." }
    t[223233] = { name = "Пояс Мідного Водолаза", fen = "A sturdy belt that keeps your diving gear held up.", fua = "Міцний пояс, що утримує ваше водолазне спорядження." }
    t[223234] = { name = "Поножі Мідного Водолаза", fen = "You won't be feeling any pressure in these greaves.", fua = "У цих поножах ви не відчуєте жодного тиску." }
    t[223235] = { name = "Чоботи Мідного Водолаза", fen = "These heavy boots are perfect for walking along the ocean floor.", fua = "Ці важкі чоботи ідеальні для прогулянок океанічним дном." }
    t[223236] = { name = "Рукавички Мідного Водолаза", fen = "The gloves are comfortable and dry (on the inside).", fua = "Рукавички зручні та сухі (зсередини)." }
    t[223243] = "Комплект: Синій Водолазний Костюм"
    t[223244] = { name = "Комплект: Водолазний Костюм Найглибших Глибин", fen = "Take to the bottom of the seas in a suit that protects and insulates.", fua = "Спустіться на дно морів у костюмі, що захищає та зберігає тепло." }
    t[223245] = "Комплект: Рибалка Безодні"
    t[223246] = "Комплект: Мідний Водолазний Костюм"
