    t[223282] = { name = "Синя Риба Прадавніх Богів", fen = "Teaches you how to summon this mount. This is a flying mount.", fua = "Навчає вас прикликати цей засіб пересування. Це летючий засіб пересування." }
    t[223285] = { name = "Зіпсований Бегемот Підсвіту", fen = "Teaches you how to summon this mount. This is a flying mount.", fua = "Навчає вас прикликати цей засіб пересування. Це летючий засіб пересування." }
    t[223286] = { name = "Ках, Легенда Глибин", fen = "Teaches you how to summon this mount. This is a flying mount.", fua = "Навчає вас прикликати цей засіб пересування. Це летючий засіб пересування." }
    t[223339] = { name = "Триші", fen = "Teaches you how to summon this companion.", fua = "Навчає тебе викликати цього супутника." }
    t[223409] = { name = "Фіолетова Мішень Боягуза", fen = "You are literally putting a target on your back.", fua = "Ви буквально вішаєте мішень собі на спину." }
    t[223410] = { name = "Багряний Колій", fen = "The bold red colors are of little comfort to the person being stabbed.", fua = "Сміливі червоні барви мало втішають того, кого штрикають." }
    t[223411] = { name = "Сапфіровий Колій", fen = "The cool blue colors provide no relief to the person being stabbed.", fua = "Холодні сині барви ніяк не втішають того, кого штрикають." }
    t[223412] = { name = "Багряна Бойова Глефа", fen = "The bright red blade hides the blood of your enemies almost too well.", fua = "Яскраво-червоне лезо приховує кров ваших ворогів аж надто добре." }
    t[223413] = { name = "Сапфірова Бойова Глефа", fen = "The blood of your enemies will stand out on the cool blue blades.", fua = "Кров ваших ворогів яскраво вирізнятиметься на холодних синіх лезах." }
    t[223414] = { name = "Багряна Сокира Асиметрії", fen = "Some would call the asymmetrical blades beautiful.", fua = "Дехто назвав би ці асиметричні леза прекрасними." }
    t[223415] = { name = "Сапфірова Сокира Асиметрії", fen = "Not every weapon has to be perfectly balanced.", fua = "Не кожна зброя має бути ідеально збалансована." }
    t[223416] = "Морероджений Клинок"
    t[223417] = "Сяйливий Морероджений Клинок"
    t[223418] = { name = "Арсенал: Морероджені Клинки", fen = "Forged by the magesmith Luminarian, this blade was quenched in the enchanted pools of Lathar'Lazal.", fua = "Викуваний магоковалем Лумінаріаном, цей клинок гартували в зачарованих водоймах Латар'Лазалу." }
    t[223419] = "Вогнероджений Клинок"
    t[223420] = "Сяйливий Вогнероджений Клинок"
    t[223421] = { name = "Арсенал: Вогнероджені Клинки", fen = "Akin to the mystical Quel'Serrar, and forged by the magesmith Luminarian, it was one of the Prismatic Blades.", fua = "Споріднена з містичним Квел'Серраром і викувана магоковалем Лумінаріаном, вона була однією з Призматичних Клинків." }
    t[223422] = { name = "Багряна Клинкова Мушкетон-Рушниця", fen = "If the blast doesn't fell your enemy, the blades at the end will certainly help.", fua = "Якщо постріл не звалить вашого ворога, клинки на кінці неодмінно допоможуть." }
    t[223423] = { name = "Сапфірова Клинкова Мушкетон-Рушниця", fen = "The blades should be used as a last resort.", fua = "Клинки слід пускати в хід лише в крайньому разі." }
    t[223425] = { name = "Проста Багряна Чарівна Паличка", fen = "A simple wand with a touch of scarlet.", fua = "Проста чарівна паличка з відтінком багрянцю." }
    t[223426] = { name = "Проста Сапфірова Чарівна Паличка", fen = "A simple wand with a touch of sapphire.", fua = "Проста чарівна паличка з відтінком сапфіру." }
    t[223429] = { name = "Багряний Посох Заклинача", fen = "A classic staff from a simpler time.", fua = "Класичний посох із простіших часів." }
    t[223430] = { name = "Сапфіровий Посох Заклинача", fen = "A classic staff from a simpler time.", fua = "Класичний посох із простіших часів." }
    t[223433] = { name = "Багряний Фоліант Санрівера", fen = "Detailed arcane notes and diagrams can be found within this Sunreaver's tome.", fua = "У цьому фоліанті Санрівера можна знайти докладні чародійні нотатки й схеми." }
    t[223434] = { name = "Сапфіровий Таласійський Фоліант", fen = "Thalassian runes carved upon the spine of the book serve as an arcane-lock, protecting the contents of this book.", fua = "Таласійські руни, викарбувані на корінці книги, слугують чародійним замком, що захищає її вміст." }
