    t[225974] = { name = "Шапка Юнги", fen = "Form fitting and head warming.", fua = "Добре сидить і гріє голову." }
    t[225975] = { name = "Патронташ Алхіміка", fen = "For when you can't risk running out of Noggenfogger Elixirs.", fua = "Для тих випадків, коли не можна ризикувати лишитися без Еліксирів Ноггенфоггера." }
    t[225976] = { name = "Витончені Рукавички Лісу", fen = "Perfect for one of Yserra's famed emerald balls.", fua = "Чудово підходять для одного зі славнозвісних смарагдових балів Ісери." }
    t[225977] = { name = "Класична Камуфляжна Туніка", fen = "A simple tabard for blending in.", fua = "Проста туніка, щоб злитися з оточенням." }
    t[225978] = { name = "Бойова Глефа Скверного Узлісся", fen = "Forged in the Emerald Nightmare from the fel energies of a thousand demons.", fua = "Викувана у Смарагдовому Жахітті зі скверної енергії тисячі демонів." }
    t[225979] = { name = "Нефритовий Клинок Забороненого", fen = "Earn accolades as you break through military blockades or participate in parades wielding this... blade's... hilt.", fua = "Здобувайте відзнаки, проривайтеся крізь військові блокади чи беріть участь у парадах, тримаючи... руків'я цього... клинка." }
    t[225980] = { name = "Високоякісний Клинок Забороненого", fen = "A well-made blade for a masquerade.", fua = "Добротний клинок для маскараду." }
    t[225982] = { name = "Осяйний Сигіл Володаря Грабунку", fen = "Blessed by a tidesage, this staff has never steered a Plunderlord wrong.", fua = "Благословлений приливним мудрецем, цей посох ніколи не збивав Володаря Грабунку з істинного шляху." }
    t[225983] = { name = "Осяйна Ручна Гармата Володаря Грабунку", fen = "Sometimes the point a Plunderlord has to make needs to be delivered with a bang.", fua = "Інколи думку Володаря Грабунку треба донести з гуркотом." }
    t[225990] = { name = "Осяйний Абордажний Меч Володаря Грабунку", fen = "With this blade you can be both dashing and slashing.", fua = "З цим клинком ви будете і блискучі, і ріжучі." }
    t[225991] = { name = "Осяйна Рапіра Володаря Грабунку", fen = "A well-armed Plunderlord always knows how to make a point.", fua = "Добре озброєний Володар Грабунку завжди знає, як донести свою думку гостро." }
    t[225992] = { name = "Осяйний Головоруб Володаря Грабунку", fen = "There's no such thing as nearly-headless with this axe.", fua = "З цією сокирою не буває «майже без голови»." }
    t[225993] = { name = "Проклятий Мідний Арбалет", fen = "Ye shall never be sated 'til all Pieces of Hate be gathered from the storm.", fua = "Ти не знатимеш спокою, доки всі Уламки Ненависті не буде зібрано зі шторму." }
    t[225994] = { name = "Простий Мідний Посох", fen = "Not recommended for irrigation.", fua = "Не рекомендовано для зрошення." }
