    t[228967] = { name = "Дещиця Ненависті", fen = "The face of this cryptic coin depicts a goblin skull.", fua = "На лицьовому боці цієї загадкової монети зображено ґоблінський череп." }
    t[228968] = { name = "[DNT]Phoenix Cold Brew", fen = "It may be brewed cold, but it is all fire.", fua = "Хай заварене холодним способом, та воно — суцільний вогонь." }
    t[228969] = { name = "[DNT]Enchanted Espresso", fen = "Brewed in secret by the Kirin Tor from Suramar beans.", fua = "Таємно зварене Кірін-Тором із зерен Сурамару." }
    t[228970] = { name = "[DNT]Highmountain Mocha", fen = "The perfect blend of Zuldazar beans, Stranglethorn cocoa, and yak's milk.", fua = "Ідеальна суміш зерен Зулдазару, какао зі Скельмандрівного Лісу та якового молока." }
    t[228971] = { name = "[DNT]Captain's Cappuccino", fen = "Popular among Kul Tirans from the admiralty down to the fisherfolk.", fua = "Популярне серед кул-тірасців, від адміралтейства до рибалок." }
    t[228972] = { name = "[DNT]Darkshore Decaf", fen = "The kaldorei have little need for caffeine.", fua = "Калдорай майже не потребують кофеїну." }
    t[228973] = { name = "[DNT]Royal Tea", fen = "Sip like a king!", fua = "Сьорбай, мов король!" }
    t[228974] = { name = "[DNT]Kalimdoricano", fen = "A special blend of beans from across the continent.", fua = "Особлива суміш зерен з усього континенту." }
    t[228976] = "Обвуглена Святкова Скриня"
    t[228977] = "Обгоріла Записка про Викуп"
    t[228983] = "Кристалізована Святкова Скриня"
    t[228985] = "Блискуча Записка про Викуп"
    t[228986] = { name = "Купонна Книжка Стиліста", fen = "Acquired from Griftah's secret collection, these universally accepted tickets provide unlimited free haircuts.", fua = "Здобута з таємної колекції Ґрифтаха, ці всюди прийняті квитки дають необмежену кількість безкоштовних стрижок." }
    t[228987] = "Сувій Скверноскутого Зв'язку"
    t[228989] = { name = "Ліцензія на Приборкання Екзотичних Звіряток", fen = "Provides legal documentation justifying your ownership of lesser-known companion pets.", fua = "Надає юридичні документи, що підтверджують ваше право володіти маловідомими улюбленцями." }
    t[228990] = "Пляшка Пари"
    t[228991] = { name = "Камінь Пророцтва", fen = "Vashti assures you this stone is very, VERY important for the future.", fua = "Вашті запевняє вас, що цей камінь дуже, ДУЖЕ важливий для майбутнього." }
    t[228995] = { name = "Золотий Мафін", fen = "A golden idol in the shape of a muffin. It seems completely pointless.", fua = "Золотий ідол у формі мафіна. Здається геть безглуздим." }
    t[228996] = "Реліквія Кристалічних Зв'язків"
    t[229007] = { name = "Кров Прадавнього Шамана", fen = "The E'ko is potent with dis one.", fua = "Е'ко в цій штуці потужне." }
    t[229046] = "Статуя Вартового"
    t[229047] = "Герб Нічних Ельфів"
    t[229048] = "Герб Людей"
    t[229049] = "Герб Орків"
    t[229054] = { name = "Дзеркало Вартового", fen = "A statuette of an owl with a gyroscopic mirror capable of redirecting complex light signals.", fua = "Статуетка сови з гіроскопічним дзеркалом, здатним перенаправляти складні світлові сигнали." }
    t[229059] = { name = "Арсенал: Герби Королівства", fen = "When chaos gripped Azeroth, these factions shaped the fate of all.", fua = "Коли хаос охопив Азерот, ці фракції визначили долю всіх." }
    t[229128] = { name = "Ведмідь Гармонійних Вітань", fen = "Teaches you how to summon this mount.", fua = "Навчає тебе викликати цього їздового." }
    t[229164] = "Клубок Пряжі"
    t[229196] = { name = "Ескіз Бакара", fen = "Some aspiring artist must have drawn this and left it here. The drawing resembles a small bakar.", fua = "Мабуть, якийсь художник-початківець намалював це й залишив тут. Малюнок нагадує маленького бакара." }
    t[229197] = { name = "[DNT]Sack of Coffee Beans", fen = "One of Meerah's lost sacks of coffee beans.", fua = "Один із загублених Мірою мішків кавових зерен." }
    t[229198] = { name = "Туз Повітря", fen = "This depicts a hand emerging from a cloud, gripping a sword encircled by a crown.", fua = "Зображує руку, що виринає з хмари, стискаючи меч, оповитий короною." }
    t[229199] = { name = "Двійка Повітря", fen = "This depicts a blindfolded figure balancing two strong winds upon their shoulders.", fua = "Зображує постать із зав'язаними очима, що балансує на плечах два сильні вітри." }
    t[229200] = { name = "Трійка Повітря", fen = "This depicts three jets of stormy wind piercing a heart, with tumultuous clouds and rain behind.", fua = "Зображує три струмені буремного вітру, що пронизують серце, а позаду — бентежні хмари й дощ." }
    t[229201] = { name = "Четвірка Повітря", fen = "This depicts the effigy of a knight in the attitude of prayer, at full length upon, presumably, their tomb.", fua = "Зображує статую лицаря в молитовній позі, на повний зріст, імовірно, на його гробниці." }
    t[229202] = { name = "П'ятірка Повітря", fen = "This depicts a disdainful man scowling at two retreating and dejected figures who've left their sacks of air lying upon the ground. He carries two others on his left shoulder, and a third is in his right hand.", fua = "Зображує зневажливого чоловіка, що супиться на дві постаті, які відступають у зневірі, покинувши свої міхи з вітром на землі. Ще два він несе на лівому плечі, а третій тримає в правій руці." }
    t[229203] = { name = "Шістка Повітря", fen = "This depicts a ferrier carrying passengers in their boat to the farther shore. The course is smooth, and seeing that the freight is light, it may be noted that the work is not beyond their strength.", fua = "Зображує перевізника, що везе пасажирів у своєму човні до дальнього берега. Хід рівний, а оскільки вантаж легкий, видно, що праця ця йому до снаги." }
    t[229204] = { name = "Сімка Повітря", fen = "This depicts a person in the act of carrying five winds away rapidly. Two other winds rest on the ground, and a camp is close by.", fua = "Зображує особу, що поспіхом несе геть п'ять вітрів. Ще два вітри лежать на землі, а поряд — табір." }
    t[229205] = { name = "Вісімка Повітря", fen = "This depicts a bound and blindfolded captive, surrounded by eight tumultuous winds. Yet, it is of temporary restraint rather than of irrevocable bondage.", fua = "Зображує зв'язаного бранця із зав'язаними очима, оточеного вісьмома буремними вітрами. Та це радше тимчасові пута, ніж невідворотна неволя." }
    t[229206] = { name = "Туз Вогню", fen = "This depicts a hand emerging from a burning ball of fire, grasping a wand encircled by smoke.", fua = "Зображує руку, що виринає з палаючої вогняної кулі, стискаючи чарівну паличку, оповиту димом." }
    t[229207] = { name = "Двійка Вогню", fen = "This depicts a tall figure looking out from a battlement roof over the sea and shore. They hold a globe in their right hand and a burning staff in their left, resting it on the battlement. Another burning staff is fixed in a ring to the figure's right.", fua = "Зображує високу постать, що дивиться з даху фортечного муру на море й узбережжя. У правій руці вона тримає кулю, а в лівій — палаючу палицю, спираючи її на зубець муру. Ще одна палаюча палиця закріплена в кільці праворуч від постаті." }
    t[229208] = { name = "Трійка Вогню", fen = "This depicts a calm, stately figure with their back turned, looking from a cliff's edge at ships passing over the sea beyond. Three staves are planted in the ground, each holding a lantern, and the figure leans slightly on one of them.", fua = "Зображує спокійну, статечну постать, обернену спиною, що дивиться з краю скелі на кораблі, які пропливають морем удалині. Три палиці встромлені в землю, кожна з ліхтарем, і постать злегка спирається на одну з них." }
    t[229209] = { name = "Четвірка Вогню", fen = "This depicts four large pillars in the foreground, with a grand garland of the purest flame suspended between them. Two figures hold up fragrant flowers, and at their side is a bridge over a moat leading to an old manor.", fua = "Зображує чотири великі колони на передньому плані, між якими висить пишна гірлянда з найчистішого полум'я. Дві постаті здіймають запашні квіти, а обіч них міст через рів веде до старого маєтку." }
    t[229210] = { name = "П'ятірка Вогню", fen = "This depicts a posse of five youths brandishing staves as if in sport. It is mimic warfare, and their eyes burn with fire.", fua = "Зображує ватагу з п'яти юнаків, що розмахують палицями, наче забавляючись. Це удаваний бій, а їхні очі палають вогнем." }
    t[229211] = { name = "Шістка Вогню", fen = "This depicts a figure on horseback adorned with a laurel crown and wielding a flaming sword. Five footmen with similar flaming swords are at the figure's side.", fua = "Зображує постать верхи на коні, увінчану лавровим вінком і з палаючим мечем у руці. П'ятеро піхотинців із такими ж палаючими мечами стоять обіч постаті." }
    t[229212] = { name = "Сімка Вогню", fen = "This depicts a determined figure standing on a rugged hill, holding a torch high above. Six other torches are being raised towards them from below.", fua = "Зображує рішучу постать, що стоїть на крутому пагорбі, тримаючи високо смолоскип. Знизу до неї здіймають ще шість смолоскипів." }
    t[229213] = { name = "Вісімка Вогню", fen = "This depicts a flight of eight flaming arrows streaking the heavens as they draw to the end of their course. What they signify is at hand--it may even be on the threshold.", fua = "Зображує політ восьми палаючих стріл, що креслять небо, добігаючи кінця свого шляху. Те, що вони віщують, уже близько — можливо, навіть на порозі." }
    t[229214] = { name = "Туз Морозу", fen = "This depicts a hand emerging from lands covered in freshly fallen snow, clasping the stem of a goblet filled to overflowing with steaming water.", fua = "Зображує руку, що виринає із земель, укритих свіжим снігом, стискаючи ніжку келиха, переповненого паруючою водою." }
    t[229215] = { name = "Двійка Морозу", fen = "This depicts two youths standing in a winter scene, toasting each other with flagons made of the purest ice.", fua = "Зображує двох юнаків у зимовому краєвиді, що цокаються кухлями з найчистішого льоду." }
    t[229216] = { name = "Трійка Морозу", fen = "This depicts revelers dancing in a garden with cups uplifted as if pledging to one another. Soft snow falls around them.", fua = "Зображує гуляк, що танцюють у саду з піднятими чашами, ніби складаючи одне одному обітницю. М'який сніг падає довкола них." }
    t[229217] = { name = "Четвірка Морозу", fen = "This depicts a figure draped in furs, sitting under a pine tree, contemplating three chalices resting in the snow before them. An arm issuing from a cloud offers the figure a fourth chalice. Their expression betrays discontentment.", fua = "Зображує постать, закутану в хутра, що сидить під сосною й споглядає три келихи, які лежать у снігу перед нею. Рука, що виринає з хмари, пропонує постаті четвертий келих. Її вираз обличчя виказує невдоволення." }
    t[229218] = { name = "П'ятірка Морозу", fen = "This depicts a dark, cloaked figure looking sideways at three prone cups resting in pools of water. Two other cups stand upright behind the figure on pedestals of ice. In the background, a bridge leads to a small keep.", fua = "Зображує темну постать у каптурі, що скоса дивиться на три перекинуті чаші, які лежать у калюжах води. Ще дві чаші стоять прямо позаду постаті на крижаних постаментах. На задньому плані міст веде до невеликої твердині." }
    t[229219] = { name = "Шістка Морозу", fen = "This depicts children in an old garden, watering flowers with cups full of melting snow.", fua = "Зображує дітей у старому саду, що поливають квіти чашами, повними талого снігу." }
    t[229220] = { name = "Сімка Морозу", fen = "This depicts strange visions pouring from seven chalices made of the purest ice. But these images are those of a fantastic spirit.", fua = "Зображує дивні видіння, що ллються із семи келихів із найчистішого льоду. Та ці образи — лише витвір примхливого духу." }
    t[229221] = { name = "Вісімка Морозу", fen = "This depicts a figure of a dejected aspect walking away, leaving behind the cups of its fortune, enterprise, undertaking, or previous concern to be engulfed by the encroaching ice.", fua = "Зображує постать із пригніченим виглядом, що йде геть, лишаючи позаду чаші свого щастя, починань, справ чи колишніх турбот, аби їх поглинула наступаюча крига." }
    t[229222] = { name = "Туз Землі", fen = "This depicts a hand emerging from the rocky ground in a cloud of dust holding up a stone disk.", fua = "Зображує руку, що виринає з кам'янистого ґрунту в хмарі пилу, тримаючи кам'яний диск." }
    t[229223] = { name = "Двійка Землі", fen = "This depicts a child in the act of dancing with a stone disk in either hand. The disks are joined by that endless cord, which is like the number 8 reversed.", fua = "Зображує дитину, що танцює з кам'яним диском у кожній руці. Диски з'єднані тим нескінченним шнуром, що нагадує перевернуту цифру 8." }
    t[229224] = { name = "Трійка Землі", fen = "This depicts a sculptor at work in a monastery. The apprentice has received their reward and is now at work in earnest.", fua = "Зображує скульптора за роботою в монастирі. Учень отримав свою винагороду й тепер працює щиро." }
    t[229225] = { name = "Четвірка Землі", fen = "This depicts a crowned figure with a stone disk over its head, clasping another disk with hands and arms and two more disks under its feet. They hold to that which they have.", fua = "Зображує увінчану постать із кам'яним диском над головою, що руками й раменами стискає ще один диск, а ще два має під ногами. Вона тримається за те, що має." }
    t[229226] = { name = "П'ятірка Землі", fen = "This depicts two beggars in a dust storm as they pass a window lighted by five glowing stone disks.", fua = "Зображує двох жебраків у піщаній бурі, які проходять повз вікно, осяяне п'ятьма світними кам'яними дисками." }
    t[229227] = { name = "Шістка Землі", fen = "This depicts a person in the guise of a merchant weighing  money on a pair of scales and distributing it to the needy and distressed. It is a testimony to their own success in life, as well as to their goodness of heart.", fua = "Зображує людину в подобі купця, що зважує гроші на терезах і роздає їх нужденним та зневіреним. Це свідчення як його життєвого успіху, так і доброти його серця." }
    t[229228] = { name = "Сімка Землі", fen = "This depicts an adolescent, leaning on their staff, looking intently at seven stone disks attached to a clump of greenery on their right. One might say these were treasures and that the young one's heart was there.", fua = "Зображує юнака, що спирається на свій посох і пильно дивиться на сім кам'яних дисків, прикріплених до куща зелені праворуч від нього. Можна сказати, що це скарби й що серце юного прикипіло до них." }
    t[229229] = { name = "Вісімка Землі", fen = "This depicts an artist in stone at work, which they exhibit in the form of trophies.", fua = "Зображує митця за роботою з каменем, чиї творіння він виставляє у вигляді трофеїв." }
    t[229348] = { name = "Ключі від Інкоґнітро, Нерозшифрованого Скверноцикла", fen = "Teaches you how to summon Incognitro, the Indecipherable Felcycle.", fua = "Навчає вас прикликати Інкоґнітро, Нерозшифрованого Скверноцикла." }
    t[229350] = "Іграшка для Гризіння"
    t[229351] = { name = "Духовні Пахощі", fen = "A bowl of aromatic ambergris blessed to honor Oacha'noa.", fua = "Чаша з ароматною амброю, освячена на честь Оача'ноа." }
    t[229355] = { name = "Преміумна Торбинка Гостинців Хромі", fen = "Contains gold, valorstones, a chance for crests, and a Warbound Until Equipped item.", fua = "Містить золото, камені звитяги, шанс на герби та прив'язаний до загону до вдягання предмет." }
    t[229358] = { name = "Мініатюрний Човен Таскарів", fen = "This must belong to Maru.", fua = "Це, певно, належить Мару." }
    t[229359] = { name = "Торбинка Гостинців Хромі", fen = "Contains a Warbound Until Equipped item appropriate for your level and class.", fua = "Містить прив'язаний до загону до вдягання предмет, що відповідає вашому рівню та класу." }
    t[229361] = { name = "Ксал'атат, Клинок Чорної Імперії", fen = "Xal'atath has a mind of its own. Ignore its maddening whispers. Do not trust the lies it spins. Take from it what you need, but always remember that the dark presence in the blade is not your ally.", fua = "Ксал'атат має власну волю. Не зважайте на її божевільний шепіт. Не вірте брехні, яку вона плете. Беріть від неї те, що вам потрібно, та завжди пам'ятайте, що темна присутність у клинку — не ваш союзник." }
    t[229364] = "Герб Пошесті"
    t[229366] = { name = "Бррргл", fen = "Teaches you how to summon this companion.", fua = "Навчає тебе викликати цього супутника." }
    t[229367] = "Примарна Святкова Скриня"
    t[229368] = { name = "Ґілл'ел", fen = "Teaches you how to summon this companion.", fua = "Навчає тебе викликати цього супутника." }
    t[229369] = "Примарна Записка про Викуп"
    t[229375] = "Нейронний Збільшувач"
    t[229383] = "Сценарій Вистави"
    t[229384] = "Бутафорський Меч"
    t[229385] = "Маска Пройдисвіта"
    t[229386] = "Диригентська Паличка"
    t[229387] = "Загадки Пройдисвіта"
    t[229408] = { name = "Обгоріла Пір'їна", fen = "The feather looks battle-worn, burnt, torn in areas, and a strange green liquid is dripping off the end of it.", fua = "Пір'їна виглядає пошарпаною в боях, обгорілою, місцями подертою, а з її кінчика скрапує дивна зелена рідина." }
    t[229409] = { name = "Вискубана Пір'їна", fen = "The feather appears to have been purposely plucked and altered to be missing exactly 48 barbs on the left and has a remaining 93 barbs on the right.", fua = "Пір'їну, схоже, навмисне вискубли й змінили так, що ліворуч бракує рівно 48 борідок, а праворуч лишилося 93." }
    t[229410] = { name = "Замерзла Пір'їна", fen = "The feather is frozen and has a strange combination of scents: volcanic ash, saltwater, and engine oil.", fua = "Пір'їна замерзла й має дивне поєднання запахів: вулканічний попіл, солона вода й машинна олія." }
    t[229411] = { name = "Звичайна Пір'їна", fen = "The feather appears unaltered as expected at the start of a journey.", fua = "Пір'їна виглядає незміненою, як і очікувано на початку подорожі." }
    t[229413] = { name = "Костюм «Догг-Сарон»", fen = "A re-labeled knockoff of an old Hallow's End costume.", fua = "Перейменована підробка старого костюма зі Свята Тіней." }
    t[229414] = "Молот Мойри Тауріссан"
    t[229418] = { name = "Вуздечка Позолоченого Бруттозавра Торговця", fen = "Teaches you how to summon this three-person mount with vendors.", fua = "Навчає викликати цього тримісного їздового з торговцями." }
    t[229425] = { name = "Бойова Булава Бронзбірдів", fen = "Forged for the kings of Ironforge, this mace will forever be tied to the line of Bronzbeard.", fua = "Викувана для королів Айронфорджа, ця булава навіки пов'язана з родом Бронзбірдів." }
    t[229426] = { name = "Прадавній Довгий Лук Амані", fen = "Painted to camouflage in the darkened pine woods of Zul'Aman.", fua = "Розмальований для маскування в темних соснових лісах Зул'Аману." }
    t[229714] = { name = "Навушники з Гербом Лева", fen = "For when you really don't want to be bothered on the Deeprun Tram.", fua = "Для тих випадків, коли тебе геть не хочуть турбувати в Глибинному Трамваї." }
    t[229720] = { name = "Навушники Клану Морозного Вовка", fen = "For those cold Alterac winters.", fua = "Для тих холодних альтеракських зим." }
    t[229807] = { name = "Вінець Крижано-Блакитної Троянди", fen = "Even kings and roses in the cold north can show their thorns.", fua = "Навіть королі й троянди на холодній півночі можуть показати свої шипи." }
    t[229808] = { name = "Блакитна Серпанкова Сукня", fen = "Perfect for indoor winter events.", fua = "Ідеально для зимових подій у приміщенні." }
    t[229811] = { name = "Морозом Травлений Кинджал", fen = "A cruel blade knapped from impossibly hard glacial ice and etched with runes of hatred.", fua = "Жорстокий клинок, висічений із неймовірно твердого льодовикового льоду й вкритий травленими рунами ненависті." }
    t[229812] = { name = "Холодна Сокира", fen = "For those times when you lose your chill.", fua = "Для тих миттєвостей, коли втрачаєш холоднокровність." }
    t[229813] = { name = "Кристалічний Довгий Лук Небес", fen = "Gives \"shooting star\" a new meaning.\n\n<Unique Ammunition>", fua = "Надає виразу «падуча зоря» нового змісту.\n\n<Унікальні боєприпаси>" }
    t[229814] = { name = "Віяло Прохолоди", fen = "Personal climate changer.", fua = "Особистий змінювач клімату." }
    t[229815] = { name = "Повітряний Посох Небесної Відьми", fen = "Elevate your combat.", fua = "Піднеси свій бій на новий рівень." }
    t[229816] = { name = "Повітряна Чарівна Паличка Небесної Відьми", fen = "There's not a star in heaven that it can't reach.", fua = "Немає на небі зірки, до якої вона б не дотягнулася." }
    t[229817] = { name = "Чарівний Повітряний Довгий Лук", fen = "This whispersoft songbird will be the last thing you hear.\n\n<Unique Ammunition>", fua = "Ця тихенька, мов шепіт, співоча пташка стане останнім, що ти почуєш.\n\n<Унікальні боєприпаси>" }
