    t[229908] = "М'яка Іграшка"
    t[229913] = { name = "Лист від Айси", fen = "A handwritten letter from Aysa.", fua = "Рукописний лист від Айси." }
    t[229958] = { name = "Оздоблена Пір'їна", fen = "The feather has been decorated with ancient Arakkoa beading. It appears to have fallen from a great height as some of the beads have shattered.", fua = "Пір'їну оздоблено давнім намистом аракоа. Схоже, вона впала з великої висоти, бо деякі намистини розбилися." }
    t[229960] = { name = "Радоносець XL", fen = "You WILL be cheerful - or else!", fua = "Ти БУДЕШ веселим — або начувайся!" }
    t[229961] = { name = "Зацукрований Ніж", fen = "The more you lick it, the sharper it gets.", fua = "Чим більше його лижеш, тим гострішим він стає." }
    t[229962] = { name = "Верхівка Дерева", fen = "If a tree impales someone in the woods and nobody is around... at least they heard it.", fua = "Якщо дерево проштрикне когось у лісі, а навколо нікого немає... принаймні всі це почують." }
    t[229963] = { name = "Великий Зацукрований Клинок", fen = "Guaranteed to cut tongues and enemies!", fua = "Гарантовано ріже язики й ворогів!" }
    t[229968] = { name = "Щедрий Бенкет", fen = "This handwritten note looks like a list of instructions, but none of it makes any sense. Maybe someone in Booty Bay can help decipher this.", fua = "Ця рукописна записка схожа на перелік вказівок, але жодна з них не має сенсу. Можливо, хтось у Затоці Здобичі допоможе її розшифрувати." }
