    t[232377] = { name = "Сироп від Кашлю Дідуся Громовара", fen = "A sip a day keeps the graveyard at bay. Served hot with two sticks of cinnamon.", fua = "Ковток на день — і цвинтар почекає. Подається гарячим із двома паличками кориці." }
    t[232378] = { name = "Смажена Курка без Витребеньок від Дженкінса", fen = "\"Double the herbs, none of the spices. Still worth dying for!\" -Mama Jenkins", fua = "\"Удвічі більше зілля, жодних спецій. І все одно варта того, щоб за неї померти!\" — Мама Дженкінс" }
