    t[242522] = { name = "Гротескний Казан Відступників", fen = "Toil and Trouble was Blight Boar's most avant-garde album.", fua = "\"Праця і Біда\" був найавангарднішим альбомом Чумного Вепра." }
    t[242523] = { name = "Казан Виючої Баньші", fen = "The brewing methods of the Forsaken are as effective as they are nauseating.", fua = "Способи варіння Відступників настільки ж дієві, наскільки й огидні." }
    t[242524] = "Хворобливий Казан Відступників"
    t[242525] = { name = "Пророча Сокира Великого Майстра", fen = "The weapon of choice for a frontline combatant.", fua = "Зброя на вибір для бійця передової." }
    t[242526] = { name = "Синя Сокира Великого Майстра", fen = "The weapon of choice for a frontline combatant.", fua = "Зброя на вибір для бійця передової." }
    t[242527] = { name = "Королівська Сокира Великого Майстра", fen = "Smoke before fire.", fua = "Диму без вогню не буває." }
    t[242528] = { name = "Біла Сокира Великого Майстра", fen = "Your enemies are mere pawns.", fua = "Ваші вороги — лише пішаки." }
    t[242539] = { name = "Пророча Булава Великого Майстра", fen = "Nicknamed \"the Midnight Sweep\", Medivh was known to clear his game board of all pieces and participants with a mighty swing of this weapon.", fua = "Прозваний «Опівнічним Замахом», Медів був відомий тим, що змітав зі своєї ігрової дошки всі фігури й усіх учасників могутнім замахом цієї зброї." }
    t[242540] = { name = "Синя Булава Великого Майстра", fen = "A proper weapon for a king.", fua = "Гідна зброя для короля." }
    t[242541] = { name = "Королівська Булава Великого Майстра", fen = "Knight to head.", fua = "Конем по голові." }
    t[242542] = { name = "Біла Булава Великого Майстра", fen = "The swing of this mace really throws off defenders.", fua = "Замах цієї булави добряче збиває захисників з пантелику." }
    t[242627] = "Крижаний Клинок Відступників"
    t[242628] = { name = "Гротескний Клинок Відринутих", fen = "It squeals in delight as it carves through flesh and bone.", fua = "Він верещить від насолоди, прорізаючи плоть і кістку." }
    t[242629] = { name = "Клинок Виючої Банші", fen = "No wound from this blade ever truly heals.", fua = "Жодна рана від цього клинка ніколи по-справжньому не загоюється." }
