    t[242632] = { name = "Гротескний Великий Клинок Відринутих", fen = "Every body it puts into the ground becomes a nursery for contagion.", fua = "Кожне тіло, яке він укладає в землю, стає розсадником зарази." }
    t[242633] = { name = "Великий Клинок Виючої Банші", fen = "The undead don't have much use for tombstones. Unless... it's a sword.", fua = "Неживим мало пуття з надгробків. Хіба що... це меч." }
