    t[250314] = { name = "Звичайна Глефа Мисливця", fen = "Training with a double-sided blade often leads to excessive wounds and the occasional lost limb.", fua = "Тренування з дволезим клинком часто закінчується зайвими ранами, а часом і втраченою кінцівкою." }
