    t[250627] = { name = "Заборонена Виделка", fen = "A fork from the Forbidden Reach. It's not that the fork itself is forbidden. That would be silly.", fua = "Виделка із Заборонених Берегів. Сама виделка не заборонена. Це було б безглуздо." }
    t[250689] = "Катувальна Диба Легіону"
    t[250690] = "Палаюча Скверною Смолоскип Володаря Ередарів"
    t[250691] = "Шкіряний Гобелен з Іклами"
    t[250692] = "Стяг зі Шкури Гострокрила"
    t[250693] = "Вівтар Опоганеного Полум'я"
    t[250694] = { name = "Драконяче Ковадло Металяра", fen = "Once used to shape metal purely for war, these anvils are now used by dracthyr artisans to make whatever they want.", fua = "Колись на цих ковадлах кували метал лише для війни, а тепер майстри-драктири роблять на них усе, що забажають." }
    t[250695] = { name = "Репліка: Молот Гратардорму", fen = "A replica of a legendary hammer once used to swear an oath of vengeance. These replicas are often used by blacksmiths to infuse their craft with a bit of mystique.", fua = "Репліка легендарного молота, яким колись скріпили клятву помсти. Такі репліки часто використовують ковалі, щоб додати своїм виробам трохи таємничості." }
    t[250696] = { name = "Лійка Садівника", fen = "It's a watering can. Everyone needs a watering can. Even dracthyr.", fua = "Це лійка. Лійка потрібна кожному. Навіть драктирам." }
    t[250697] = { name = "Драконяча Кафедра Аукціоніста", fen = "A stylish lectern. Tavern tales tell that standing at once of these makes your speech increase in speed threefold.", fua = "Стильна кафедра. У корчмах кажуть, що той, хто стане за неї, починає говорити втричі швидше." }
    t[250698] = { name = "Прапорець Обсидіанового Вартового", fen = "A banner proudly displaying the symbol of the Obsidian Warder weyrn.", fua = "Стяг, що гордо несе символ вейрну Обсидіанового Вартового." }
    t[250699] = { name = "Прапорець Темного Кігтя", fen = "A banner proudly displaying the symbol of the Dark Talon weyrn.", fua = "Стяг, що гордо несе символ вейрну Темного Кігтя." }
    t[250700] = { name = "Смажена Бараняча Нога", fen = "It's a succulent roasted leg of ram. Despite this, it is named after the inn of Valdrakken, and not just because it's a roasted leg of ram.", fua = "Це соковита смажена бараняча нога. Попри це, названа вона на честь корчми у Валдраккені, і не лише тому, що це смажена бараняча нога." }
    t[250701] = { name = "Драконячий Торговий Візок", fen = "A status symbol for some, this stylish cart will let you transport anything smaller than it to wherever you need it to be.", fua = "Для декого це символ статусу. Цей стильний візок дасть змогу перевезти будь-що менше за нього туди, куди вам треба." }
    t[250702] = { name = "Мірчі Терези Майстра", fen = "Useful for measuring out ingredients or anything else that need weighing. Not recommended for weighing anything larger than a small dog. Or a very large rat.", fua = "Зручні, щоб відмірювати інгредієнти чи будь-що інше, що треба зважити. Не рекомендовано важити щось більше за малого пса. Або за дуже великого щура." }
    t[250703] = { name = "Навчальний Кристал Воєнного Виводку", fen = "Crystals like these were once used to store Neltharion's teachings for the dracthyr. Not this one, though.", fua = "Такі кристали колись зберігали вчення Нелтаріона для драктирів. Та не цей." }
    t[250704] = { name = "Стародавній Пристрій Вейрну", fen = "An ancient device from one of the dracthyr weyrns. It doesn't work anymore other than making a colorful glow.", fua = "Стародавній пристрій з одного з вейрнів драктирів. Він уже не працює, лише видає барвисте сяйво." }
