    t[253523] = { name = "Кальян Асталора", fen = "The same type of hookah found in Astalor's Sanctum. Comes with a card that says \"With my compliments - A\".", fua = "Той самий кальян, що стоїть у Святилищі Асталора. До нього додається картка з написом «З найкращими побажаннями — А»." }
    t[253524] = { name = "Декоративна Пляшка Червоного Квель'Літієн 590-го Року", fen = "Some bottles of wine are for drinking, other bottles of wine are for showing off to people what you could have been drinking if you opened it. This is the latter.", fua = "Одні пляшки вина призначені, щоб їх пити, інші — щоб вихвалятися перед людьми, що ви могли б випити, якби відкоркували. Ця належить до других." }
    t[253525] = { name = "Диктофон Таласійської Академії", fen = "For when one has just the most incredible thoughts, and simply can't pick up a pen with which to write them down. Or taking notes in university while not paying attention to the lecturer.", fua = "Для тих миттєвостей, коли вам спадають на думку найнеймовірніші ідеї, а ви просто не можете взяти перо, щоб їх записати. Або щоб конспектувати в університеті, не слухаючи викладача." }
    t[253526] = { name = "Винна Вітрина Сін'дорай", fen = "Some bottles of wine are for drinking, other bottles of wine are for showing off to people what you could have been drinking if you opened it. This is the later but dialed up to the nines.", fua = "Одні пляшки вина призначені, щоб їх пити, інші — щоб вихвалятися перед людьми, що ви могли б випити, якби відкоркували. Ця належить до других, та ще й у найрозкішнішому вигляді." }
