    t[253580] = { name = "Сокирка для Заготівлі", fen = "A magical hatchet from your home neighborhood. Used to harvest lumber, which you can later use to craft decor with crafting professions.", fua = "Чарівна сокирка з вашого рідного району. Слугує для заготівлі деревини, з якої ви згодом зможете виготовляти оздоблення за допомогою ремісничих професій." }
