    t[266077] = { name = "Звичайний Чорний Сагайдак", fen = "Shadowy wisps cling to the dark feathers of these deadly barbed arrows.", fua = "Тіньові пасма чіпляються до темного пір'я цих смертоносних зазубрених стріл." }
    t[266078] = "Звичайний Синій Сагайдак"
    t[266079] = "Звичайний Бронзовий Сагайдак"
    t[266080] = { name = "Нічний Сагайдак Вартової", fen = "A standard piece of equipment for those serving in the Sentinel army.", fua = "Звичайне спорядження для тих, хто служить у війську Вартових." }
    t[266081] = { name = "Сагайдак Квел'Даніла", fen = "High Elf fletchers adorn their arrows with the shed plumeage of Hinterland Gryphons.", fua = "Лучники високих ельфів оздоблюють свої стріли опалим пір'ям грифонів Пригір'я." }
    t[266082] = "Звичайний Темно-Червоний Сагайдак"
    t[266083] = "Звичайний Морозний Сагайдак"
    t[266084] = { name = "Лісовий Сагайдак Далекоходів", fen = "Bears the traditional gold and emerald coloration of the Farstrider rangers.", fua = "Має традиційне золото-смарагдове забарвлення вартових Далекоходів." }
    t[266085] = { name = "Звичайний Крижаний Сагайдак", fen = "Notched with blue feathers from cerulean dragonhawks, the arrows within these quivers fly with dangerous accuracy.", fua = "Стріли в цих сагайдаках, оперені синім пір'ям лазурових драконояструбів, летять із небезпечною точністю." }
    t[266086] = "Звичайний Світлий Сагайдак"
    t[266087] = { name = "Сагайдак Послушника Рен'дорай", fen = "Standard-issue training weapon for all aspirant void rangers.", fua = "Стандартна навчальна зброя для всіх послушників-вартових Порожнечі." }
    t[266088] = "Звичайний Світло-Коричневий Сагайдак"
    t[266089] = "Звичайний Блідий Сагайдак"
    t[266090] = "Звичайний Фіолетовий Сагайдак"
    t[266091] = "Звичайний Грубий Сагайдак"
    t[266092] = "Звичайний Морськозелений Сагайдак"
    t[266095] = { name = "Чоботи з Обсидіанової Луски", fen = "Shink, shink, shink... Definitely not sneaky.", fua = "Брязь, брязь, брязь... Точно не для крадькома." }
    t[266096] = { name = "Місячна Глефа Мисливиці", fen = "The moonglaive is equally dangerous in close-quarters and from afar.", fua = "Місячна глефа однаково небезпечна як у ближньому бою, так і здалеку." }
    t[266097] = { name = "Місячне Лезо Мисливиці", fen = "Pure moonlight reflects off each of the pristine blades.", fua = "Чисте місячне сяйво відбивається в кожному з бездоганних лез." }
    t[266120] = { name = "Серп Сестринства", fen = "Originally favored by the martially-skilled Sisters of Elune, this weapon became standard within the Kaldorei military.", fua = "Спершу цю зброю полюбляли вправні в бою Сестри Елуни, а згодом вона стала стандартною у війську калдореїв." }
    t[266121] = { name = "Глефа Сестринства", fen = "Before wielding an Umbra Crescent, a Warden trainee must first master the twin-bladed glaive.", fua = "Перш ніж володіти Тіньовим Серпом, учениця Вартових мусить опанувати двосічну глефу." }
    t[266122] = { name = "Нічний Шаблезуб Лучниці", fen = "As the last arrow flies, the archer's blade cuts through shadows like moonlight in the dark.", fua = "Коли летить остання стріла, лезо лучниці розтинає тіні, наче місячне сяйво в темряві." }
    t[266123] = { name = "Місячний Спис Сестринства", fen = "During the War of the Ancients, this weapon was favored by armored Priestesses spearheading into battle atop their nightsabers.", fua = "Під час Війни Прадавніх цю зброю полюбляли броньовані жриці, що очолювали бій верхи на своїх нічних шаблезубах." }
    t[266124] = { name = "Тіньовий Кіготь Лучниці", fen = "Cutting through flesh and armor alike, this blade ends fights before they can even begin.", fua = "Розтинаючи однаково й плоть, і броню, це лезо завершує бій ще до того, як він почнеться." }
    t[266125] = { name = "Зоряне Лезо Жриці", fen = "While the Sisters of Elune traditionally no longer wield glaive nor lance, many continue to carry starblades as personal armaments.", fua = "Хоч Сестри Елуни за традицією більше не володіють ні глефою, ні списом, багато з них досі носять зоряні леза як особисту зброю." }
    t[266160] = { name = "Зелені Капці Звіролова", fen = "An expert trapper is nothing without expert trappings.", fua = "Справжній звіролов — ніщо без справжнього спорядження." }
