    t[268793] = { name = "Комплект: Розмальоване Бойове Вбрання Світанкового Ловця", fen = "Per Tauren tradition, this traditional armor is worn to celebrate the shortening of the day and the slumbering of An'she during the winter solstice.", fua = "За традицією тауренів, цю обрядову броню вдягають, щоб відсвяткувати скорочення дня та засинання Ан'ше під час зимового сонцестояння." }
