    t[268830] = { name = "Стильний Коричневий Кашкет із Квітами", fen = "This hat is all the rage in Stormglen Village.", fua = "Цей капелюх — останній писк моди в Селі Штормоленд." }
    t[268831] = { name = "Стильний Чорний Кашкет", fen = "Just because you're a worgen doesn't mean you can't rock the catwalk.", fua = "Те, що ви воргена, не означає, що ви не можете блищати на подіумі." }
