    t[268893] = { name = "Комплект: Дороговказні Тотеми Сутінкового Бігуна", fen = "In the autumn and winter seasons, the Duskrunners were charged with lighting the bonfires throughout Feralas and Mashan'she.", fua = "Восени та взимку Сутінкові Бігуни мали обов'язок розпалювати багаття по всьому Фераласу та Машан'ше." }
    t[268894] = { name = "Комплект: Дороговказні Тотеми Сонценосця", fen = "Long ago, great flaming totems were carried up the highest peaks of Stonetalon to illuminate the darkness that clung to the mountains.", fua = "Давним-давно великі палаючі тотеми піднесли на найвищі вершини Кам'яного Кігтя, щоб осяяти темряву, що чіплялася за гори." }
