    t[268897] = { name = "Полум'яний Меч Сутінкового Бігуна", fen = "Through darkened jungles and night-touched plains, may the Duskrunner's flames light your way.", fua = "Крізь темні джунглі й оповиті ніччю рівнини нехай полум'я Сутінкового Бігуна освітлює ваш шлях." }
    t[268898] = { name = "Полум'яний Меч Сонценосця", fen = "Where the light of Sun's blade burned, the shadows retreated.", fua = "Там, де палало світло сонячного леза, тіні відступали." }
    t[268899] = { name = "Полум'яний Меч Світанкового Ловця", fen = "Warning: Excessive radiance may attract unwanted attention.", fua = "Попередження: надмірне сяйво може привернути небажану увагу." }
    t[268900] = "Синій Смолоскипний Клинок Соняхода"
    t[268901] = { name = "Смолоскипне Лезо Сутінкового Бігуна", fen = "According to tauren myth, An'she wielded blades of fire to cut through the encroaching shadows.", fua = "За міфами тауренів, Ан'ше володів вогняними лезами, щоб розтинати наступаючі тіні." }
    t[268902] = { name = "Смолоскипне Лезо Сонценосця", fen = "Blessed and forged during a solar eclipse, this blade bears the searing fury of An'she.", fua = "Благословенне й викуване під час сонячного затемнення, це лезо несе в собі пекучу лють Ан'ше." }
    t[268903] = { name = "Смолоскипне Лезо Світанкового Ловця", fen = "Guaranteed to brighten your day and darken your enemy's.", fua = "Гарантовано осяє ваш день і затьмарить день вашого ворога." }
