    t[268905] = { name = "Тотемна Дворучна Сокира Сутінкового Бігуна", fen = "\"We must not merely ignite the bonfires, but guard them from the darkness that seeks to extinguish An'she's Light.\" - The Duskrunner's Charge", fua = "«Ми маємо не лише розпалювати багаття, а й боронити їх від темряви, що прагне погасити Світло Ан'ше.» — Обов'язок Сутінкового Бігуна" }
    t[268906] = { name = "Тотемна Дворучна Сокира Сонценосця", fen = "The light of An'she giveth. The axe of An'she taketh.", fua = "Світло Ан'ше дарує. Сокира Ан'ше забирає." }
