    t[274404] = { name = "Тавро Праведного Поборника Закону", fen = "Don't brand the cattle. Brand the buyer. He's the one likely to stray.", fua = "Таврувати треба не худобу. Таврувати треба покупця. Саме він схильний накивати п'ятами." }
