    t[274434] = { name = "Ніж Праведного Поборника Закону", fen = "There are two kinds of people in the world: Those with a rope around the neck, and the people who have the job of doing the cutting.", fua = "У світі є два типи людей: ті, у кого петля на шиї, і ті, чия робота — рубати." }
