    t[274464] = { name = "Чорний Барвник для Житла", fen = "Allows you to apply a black color to a dyeable Decor in your house. Only usable once. Can be bought and sold on the Auction House.", fua = "Дозволяє нанести чорний колір на придатну для фарбування оздобу у вашій оселі. Лише одноразово. Можна купувати й продавати в Аукціонному Домі." }
    t[274468] = { name = "Синій Барвник для Житла", fen = "Allows you to apply a blue color to a dyeable Decor in your house once. Can be bought and sold on the Auction House.", fua = "Дозволяє один раз нанести синій колір на придатну для фарбування оздобу у вашій оселі. Можна купувати й продавати в Аукціонному Домі." }
    t[274469] = { name = "Коричневий Барвник для Житла", fen = "Allows you to apply a brown color to a dyeable Decor in your house once. Can be bought and sold on the Auction House.", fua = "Дозволяє один раз нанести коричневий колір на придатний для фарбування декор у твоєму домі. Можна купувати й продавати на аукціоні." }
    t[274470] = { name = "Зелений Барвник для Житла", fen = "Allows you to apply a green color to a dyeable Decor in your house once. Can be bought and sold on the Auction House.", fua = "Дозволяє один раз нанести зелений колір на придатний для фарбування декор у вашому домі. Можна купувати й продавати на Аукціоні." }
    t[274471] = { name = "Помаранчевий Барвник для Житла", fen = "Allows you to apply an orange color to a dyeable Decor in your house once. Can be bought and sold on the Auction House.", fua = "Дозволяє один раз нанести помаранчевий колір на придатний для фарбування декор у вашому домі. Можна купувати й продавати на Аукціоні." }
    t[274472] = { name = "Пурпуровий Барвник для Житла", fen = "Allows you to apply a purple color to a dyeable Decor in your house once. Can be bought and sold on the Auction House.", fua = "Дозволяє один раз нанести пурпуровий колір на придатну для фарбування оздобу у вашій оселі. Можна купувати й продавати в Аукціонному Домі." }
    t[274473] = { name = "Червоний Барвник для Житла", fen = "Allows you to apply a red color to a dyeable Decor in your house once. Can be bought and sold on the Auction House.", fua = "Дозволяє один раз нанести червоний колір на придатний для фарбування декор у вашому домі. Можна купувати й продавати на Аукціоні." }
    t[274474] = { name = "Білий Барвник для Житла", fen = "Allows you to apply a white color to a dyeable Decor in your house once. Can be bought and sold on the Auction House.", fua = "Дозволяє один раз нанести білий колір на придатну для фарбування оздобу у вашій оселі. Можна купувати й продавати в Аукціонному Домі." }
