    t[275063] = { name = "Пісня Фокстон про Тепло", fen = "\"As I work the metal, I remember her kindness; welcoming me as her own blood and kin.\" - A Verse of Warmth", fua = "«Працюючи з металом, я згадую її доброту: вона прийняла мене як рідну кров». — Строфа про Тепло" }
    t[275064] = { name = "Пісня Фокстон про Милосердя", fen = "\"As I etch the verses of warmth, strength and binding, may this forge-song sing of Taretha; a Foxton's Song.\"", fua = "«Карбуючи строфи про тепло, силу й узи, хай ця ковальська пісня співає про Тарету — Пісня Фокстон»." }
    t[275065] = { name = "Пісня Фокстон про Узи", fen = "\"As I bind this hilt,  I look back upon the bonds we formed. My second family in an unwelcome land.\" - A Verse of Binding", fua = "«Обмотуючи це руків'я, я згадую узи, що нас пов'язали. Мою другу сім'ю на негостинній землі». — Строфа про Узи" }
    t[275066] = { name = "Пісня Фокстон про Силу", fen = "\"As I strike the anvil, I am reminded of her unbending resilience in an unjust world.\" - A Verse of Strength", fua = "«Б'ючи по ковадлу, я згадую її незламну стійкість у несправедливому світі». — Строфа про Силу" }
    t[275230] = { name = "Браслет Дружби з Місячного Каменю", fen = "Wearing this shows the true power of friendship.", fua = "Той, хто це носить, показує справжню силу дружби." }
