    t[276245] = { name = "Тіньовий Шпильовий Яструб", fen = "Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.", fua = "Навчає вас прикликати цього їздового звіра. Цей звір змінюється залежно від вашого вміння верхової їзди та місцеперебування." }
    t[276246] = { name = "Механічно Ідентичний Пепе", fen = "Looks like Pepe. Acts like Pepe. Works like Pepe. Is not Pepe.", fua = "Виглядає як Пепе. Поводиться як Пепе. Працює як Пепе. Не Пепе." }
    t[276312] = { name = "Смолоскип Обертання Ґріфтаха", fen = "This torch allows you to hex objects, just as a voodoo doll does to a person. Having this sconce in your house will allow you to rotate your decor in any way you can imagine.", fua = "Цей смолоскип дозволяє наврочити предмети — так само, як лялька вуду наврочує людину. Якщо цей світильник стоятиме у вашому домі, ви зможете обертати декор як завгодно." }
    t[276316] = "Транспортна Платформа Світлозавіси"
    t[276318] = "Бойовий Стяг Сяйливого Воїна"
    t[276321] = "Золота Барикада Сяйливого Захисника"
    t[276405] = { name = "Елегантний Дренітовий Тесак", fen = "Like a moonlit crescent, as sharp and beautiful as the stars overhead.", fua = "Мов осяяний місяцем серп — такий же гострий і прекрасний, як зорі над головою." }
    t[276406] = { name = "Елегантний Таласитовий Тесак", fen = "The hues of green and blue shimmer as bright as the waters that once flowed around Shattrath.", fua = "Відтінки зеленого й синього мерехтять так само яскраво, як води, що колись омивали Шаттрат." }
    t[276408] = { name = "Елегантний Тесак із Вогнекаменю", fen = "When carved correctly, pyrestone radiates heat from its surface. If its edge won't hurt you, its blaze will.", fua = "Правильно вирізьблений вогнекамінь випромінює жар із поверхні. Якщо не вразить лезо, то обпече полум'я." }
    t[276409] = { name = "Велика Дренітова Бойова Сокира", fen = "The violet and sapphire hues meld as one, like the twilit skies over Karabor once did.", fua = "Фіолетовий і сапфіровий відтінки зливаються воєдино — як колись присмеркові небеса над Карабором." }
    t[276410] = { name = "Велика Таласитова Бойова Сокира", fen = "Carved from Talasite and the crystal deposits found around Terokkar Forest.", fua = "Вирізьблена з таласиту та кристалічних покладів, що трапляються довкола лісу Тероккар." }
    t[276412] = { name = "Велика Вогнекамінна Бойова Сокира", fen = "The razor edge of the pyrestone head gleams like the skies over Blade's Edge Mountains.", fua = "Гостре, як бритва, вогнекамінне лезо сяє, немов небо над Горами Леза." }
    t[276413] = { name = "Церемоніальний Дренітовий Бойовий Молот", fen = "With enough patience, expert jewelcrafters can carefully carve draenite crystals to reveal deep blue or purple shades.", fua = "Маючи досить терпіння, досвідчені ювеліри можуть обережно огранити кристали дреніту, щоб відкрити глибокі сині чи фіолетові відтінки." }
    t[276414] = { name = "Церемоніальний Таласитовий Бойовий Молот", fen = "The magical regenerative properties of talasite made this a popular ornamental weapon for priests and healers.", fua = "Завдяки магічним відновлювальним властивостям таласиту ця зброя стала популярною окрасою серед жерців і цілителів." }
    t[276416] = { name = "Церемоніальний Вогнекам'яний Бойовий Молот", fen = "The Pyrestone crown of this mace catches the light with a fiery glow.", fua = "Вогнекам'яне навершя цієї булави ловить світло вогнистим сяйвом." }
    t[276417] = { name = "Загартований у Битвах Дренітовий Бойовий Молот", fen = "In the hands of a battle-ready vindicator, no weapon is too heavy or unwieldable.", fua = "У руках готового до бою месника жодна зброя не буває надто важкою чи незграбною." }
    t[276418] = { name = "Загартований у Битвах Таласитовий Бойовий Молот", fen = "The green-blue light that emits from the globe of the mace resembles the glow of the terocones found around Terokkar.", fua = "Зеленаво-синє світло, що лине з кулі булави, нагадує сяйво терошишок, які ростуть довкола Терокара." }
    t[276421] = { name = "Загартований у Битвах Вогнекам'яний Бойовий Молот", fen = "Dangerously beautiful and devastatingly heavy.", fua = "Небезпечно гарний і нищівно важкий." }
