    t[282273] = { name = "Морозний Фетиш Крижаного Ходака", fen = "So in the storm, the settlers still, all huddled in the cold. The huntsman's form, through snow, did fade, his bells no longer tolled.'", fua = "«І в бурі поселенці завмерли, збившись у купу на холоді. Постать мисливця розтанула в снігу — і дзвони його змовкли.»" }
    t[282275] = "Жевріючий Морозний Фетиш"
    t[282276] = "Морозний Фетиш Морозного Привида"
    t[282277] = { name = "Морозний Фетиш Лісового Привида", fen = "When dark winter nights chill to the bone, cold eyes of ice and snow watch from the blackened woods.", fua = "Коли темні зимові ночі проймають холодом до кісток, із почорнілих лісів стежать холодні очі з льоду й снігу." }
    t[282287] = "Пепе-Опудало"
    t[282289] = "Жахлива Голова Вершника"
    t[282327] = "Фейський Анімагриб"
    t[282340] = "Креслення Фасаду Осінньої Клуні Вестфолу"
    t[282343] = "Креслення Фасаду Весняної Клуні Вестфолу"
    t[282347] = "Нічне Вікно Старого Мунбрука"
    t[282563] = { name = "Дзвінка Коса Крижаного Ходака", fen = "On ice and fear, the settlers held, where did their huntsman dwell? But on the wind, they heard it ring, a single haunting bell.'", fua = "«На кризі, у страху, чекали поселенці: де ж подівся їхній мисливець? Та з вітром до них долинув дзвін — один-єдиний, моторошний дзвін.»" }
    t[282564] = { name = "Жевріюча Дзвонова Коса", fen = "The frost-touched scythe shimmers like ice in the cold, starless night; a frozen scream lost in the winter's wind.", fua = "Торкнута морозом коса мерехтить, мов лід у холодну беззоряну ніч; застиглий крик, загублений у зимовому вітрі." }
    t[282565] = "Дзвінка Коса Морозного Привида"
    t[282566] = { name = "Дзвінка Коса Лісового Привида", fen = "A curved, wicked blade, touched by the very breath of ancient woods, its haunting toll rings.", fua = "Вигнуте лиховісне лезо, торкнуте самим подихом прадавніх лісів; лунає його моторошний подзвін." }
    t[282567] = { name = "Морозний Скіпетр Лісового Привида", fen = "From the roots of the dark, cold woods, something sinister seeps into the very bones of the fallen woodland beasts.", fua = "З коріння темних холодних лісів щось зловісне просякає в самі кістки полеглих лісових звірів." }
    t[282569] = "Морозний Скіпетр Морозного Привида"
    t[282570] = "Жевріючий Морозний Скіпетр"
    t[282571] = { name = "Морозний Скіпетр Крижаного Ходака", fen = "But one day they crossed, their vision skewed, winds screamed where few did dare. To find a path, he bid them stay, his bells tolled through the air.'", fua = "«Та якось рушили вони — і зір їм затуманило, вітри ревли там, де мало хто бував. Щоб шлях знайти, він наказав їм ждати — і дзвони його в повітрі лунали.»" }
    t[282641] = { name = "Пробивач Шкур Крижаного Ходака", fen = "'Through sleet and snow, led a huntsman guide, with furs and bells a-rung. When ringing tolled, his path was safe, to guide the old and young.'\n<Unique Ammunition>", fua = "«Крізь сніг і дощ мисливець вів людей — у хутрі весь, із дзвонами дзвінкими. Де дзвін лунав, там шлях безпечний був — для старих і малих.»\n<Унікальні набої>" }
    t[282643] = { name = "Жевріючий Пробивач Шкур", fen = "<Unique Ammunition>", fua = "<Унікальні Боєприпаси>" }
    t[282644] = { name = "Пробивач Шкур Морозного Привида", fen = "<Unique Ammunition>", fua = "<Унікальні Боєприпаси>" }
    t[282645] = { name = "Пробивач Шкур Лісового Привида", fen = "The trusted weapon of a skilled woodland tracker, warped by magic of a cold and twisted nature.\n<Unique Ammunition>", fua = "Надійна зброя вправного лісового слідопита, спотворена холодною й покрученою магією.\n<Унікальні набої>" }
    t[282646] = { name = "Гарячий Мотокросовий Булковоз 4000", fen = "Teaches you how to summon this mount.", fua = "Навчає тебе викликати цього їздового." }
